    const total=summary(),baseRange=compareRange();
    return `<section class="panel" id="section-2"><div class="panel-header"><div><h3>店铺投入与效率</h3><p class="caption">同平台比较 · 每家店按店日覆盖独立核验</p></div><span class="tag neutral">${scopedShops().length} 家店铺</span></div><div class="table-wrap"><table><thead><tr><th>店铺</th><th class="right">花费 / 元</th><th class="right">花费占比</th><th class="right">归因成交 / 元</th><th class="right">ROAS</th><th class="right">推广费率</th><th class="right">花费环比</th><th>店日配对</th></tr></thead><tbody>${scopedShops().map(shop=>{const s=aggregate(records(undefined,[shop])),b=aggregate(records(baseRange,[shop],'complete'));return `<tr><td><button class="quiet" data-action="shop" data-value="${shop.id}">${escape(shop.name)} ↗</button></td><td class="right">${money(s.spend)}</td><td class="right">${rate(ratio(s.spend,total.spend))}</td><td class="right">${money(s.revenue)}</td><td class="right">${multiple(s.roas)}</td><td class="right">${rate(s.fee)}</td><td class="right">${s.complete&&b.complete?change(s.spend,b.spend):'<span class="warning">覆盖不足</span>'}</td><td>${coverageStrip(s)}<small>${s.pairCount}/${s.expected} 日</small></td></tr>`}).join('')}</tbody></table></div><div class="panel-footer">花费占比仅表示已覆盖推广花费结构，不代表平台交易渠道份额。</div></section>`;
